/**
 * @file
 *
 * Implementation of the multiple precision multiplication functions.
 *
 * @ingroup bn
 */

#include "relic_core.h"
#include "relic_bn_low.h"

/*============================================================================*/
/* Private definitions                                                        */
/*============================================================================*/

#if BN_KARAT > 0 || !defined(STRIP)

/**
 * Multiplies two multiple precision integers using recursive Karatsuba
 * multiplication.
 *
 * @param[out] c			- the result.
 * @param[in] a				- the first multiple precision integer.
 * @param[in] b				- the second multiple precision integer.
 * @param[in] level			- the number of Karatsuba steps to apply.
 */
static void bn_mul_karat_imp(bn_t c, const bn_t a, const bn_t b, int level) {
	int h;
	bn_t a0, a1, b0, b1, a0b0, a1b1;
	bn_t t;
	const dig_t *tmpa, *tmpb;
	dig_t *t0;

	bn_null(a0);
	bn_null(a1);
	bn_null(b0);
	bn_null(b1);
	bn_null(a0b0);
	bn_null(a1b1);
	bn_null(t);

	/* Compute half the digits of a or b. */
	h = RLC_MIN(a->used, b->used) >> 1;

	RLC_TRY {
		/* Allocate the temp variables. */
		bn_new(a0);
		bn_new(a1);
		bn_new(b0);
		bn_new(b1);
		bn_new(a0b0);
		bn_new(a1b1);
		bn_new(t);

		a0->used = b0->used = h;
		a1->used = a->used - h;
		b1->used = b->used - h;

		tmpa = a->dp;
		tmpb = b->dp;

		/* a = a1 || a0 */
		t0 = a0->dp;
		for (int i = 0; i < h; i++, t0++, tmpa++)
			*t0 = *tmpa;
		t0 = a1->dp;
		for (int i = 0; i < a1->used; i++, t0++, tmpa++)
			*t0 = *tmpa;

		/* b = b1 || b0 */
		t0 = b0->dp;
		for (int i = 0; i < h; i++, t0++, tmpb++)
			*t0 = *tmpb;
		t0 = b1->dp;
		for (int i = 0; i < b1->used; i++, t0++, tmpb++)
			*t0 = *tmpb;

		bn_trim(a0);
		bn_trim(b0);
		bn_trim(a1);
		bn_trim(b1);

		/* a0b0 = a0 * b0 and a1b1 = a1 * b1 */
		if (level <= 1) {
#if BN_MUL == BASIC
			bn_mul_basic(a0b0, a0, b0);
			bn_mul_basic(a1b1, a1, b1);
#elif BN_MUL == COMBA
			bn_mul_comba(a0b0, a0, b0);
			bn_mul_comba(a1b1, a1, b1);
#endif
		} else {
			bn_mul_karat_imp(a0b0, a0, b0, level - 1);
			bn_mul_karat_imp(a1b1, a1, b1, level - 1);
		}

		/* t = (a1 + a0) */
		bn_add(a1, a1, a0);
		/* t2 = (b1 + b0) */
		bn_add(b1, b1, b0);

		/* t = (a1 + a0)*(b1 + b0) */
		if (level <= 1) {
#if BN_MUL == BASIC
			bn_mul_basic(t, a1, b1);
#elif BN_MUL == COMBA
			bn_mul_comba(t, a1, b1);
#endif
		} else {
			bn_mul_karat_imp(t, a1, b1, level - 1);
		}
		/* t2 = (a0*b0 + a1*b1) */
		bn_sub(t, t, a0b0);

		/* t = (a1 + a0)*(b1 + b0) - (a0*b0 + a1*b1) */
		bn_sub(t, t, a1b1);

		/* t = (a1 + a0)*(b1 + b0) - (a0*b0 + a1*b1) << h digits */
		bn_lsh(t, t, h * RLC_DIG);

		/* t2 = a1 * b1 << 2*h digits */
		bn_lsh(a1b1, a1b1, 2 * h * RLC_DIG);

		/* t = t + a0*b0 */
		bn_add(t, t, a0b0);

		/* c = t + a1*b1 */
		bn_add(t, t, a1b1);

		t->sign = a->sign ^ b->sign;
		bn_copy(c, t);
		bn_trim(c);
	}
	RLC_CATCH_ANY {
		RLC_THROW(ERR_CAUGHT);
	}
	RLC_FINALLY {
		bn_free(a0);
		bn_free(a1);
		bn_free(b0);
		bn_free(b1);
		bn_free(a0b0);
		bn_free(a1b1);
		bn_free(t);
	}
}

#endif

