void bn_mul_dig(bn_t c, const bn_t a, dig_t b) {
	bn_grow(c, a->used + 1);
	c->sign = a->sign;
	c->dp[a->used] = bn_mul1_low(c->dp, a->dp, b, a->used);
	c->used = a->used + 1;
	bn_trim(c);
}

