void bn_mul_basic(bn_t c, const bn_t a, const bn_t b) {
	int i;
	bn_t t;
	dig_t carry;

	bn_null(t);

	RLC_TRY {
		/* We need a temporary variable so that c can be a or b. */
		bn_new_size(t, a->used + b->used);
