		t->sign = a->sign ^ b->sign;
		bn_trim(t);

		/* Swap c and t. */
		bn_copy(c, t);
	}
	RLC_CATCH_ANY {
		RLC_THROW(ERR_CAUGHT);
	}
	RLC_FINALLY {
		bn_free(t);
	}
}

#endif

#if BN_MUL == COMBA || !defined(STRIP)

