#if BN_SQR == BASIC || !defined(STRIP)

void bn_sqr_basic(bn_t c, const bn_t a) {
	int i, digits;
	bn_t t;

	bn_null(t);

	digits = 2 * a->used;

	RLC_TRY {
		bn_new_size(t, digits);
		bn_zero(t);
		t->used = digits;

		for (i = 0; i < a->used - 1; i++) {
			t->dp[a->used + i + 1] =
					bn_sqra_low(t->dp + 2 * i, a->dp + i, a->used - i);
		}
		bn_sqra_low(t->dp + 2 * i, a->dp + i, 1);

		t->sign = RLC_POS;
		bn_trim(t);
		bn_copy(c, t);
	}
	RLC_CATCH_ANY {
		RLC_THROW(ERR_CAUGHT);
	}
	RLC_FINALLY {
		bn_free(t);
	}
}

#endif

#if BN_SQR == COMBA || !defined(STRIP)

void bn_sqr_comba(bn_t c, const bn_t a) {
	int digits;
	bn_t t;

	bn_null(t);

	digits = 2 * a->used;

	RLC_TRY {
		/* We need a temporary variable so that c can be a or b. */
		bn_new_size(t, digits);
		t->used = digits;

		bn_sqrn_low(t->dp, a->dp, a->used);

		t->sign = RLC_POS;
		bn_trim(t);
		bn_copy(c, t);
	} RLC_CATCH_ANY {
		RLC_THROW(ERR_CAUGHT);
	}
	RLC_FINALLY {
		bn_free(t);
	}
}

