	for (int i = 0; i < BENCH; i++) {
		bn_free(a[i]);
	}

	for (int i = 0; i < BENCH; i++) {
		bn_new(a[i]);
	}
	BENCH_SMALL("bn_clean", bn_clean(a[i]));
	for (int i = 0; i < BENCH; i++) {
