	}

	for (int i = 0; i < BENCH; i++) {
		bn_new(a[i]);
	}
	BENCH_SMALL("bn_grow", bn_grow(a[i], 2 * RLC_BN_DIGS));
	for (int i = 0; i < BENCH; i++) {
		bn_free(a[i]);
